// Era-overview cards live in their own file (see historyOverviews.js).
historyEvents.push(...historyOverviews);

async function run() {
  await connectDB();
  let added = 0,
    updated = 0,
    failed = 0;

  for (const data of historyEvents) {
    try {
      const result = await HistoryEvent.findOneAndUpdate(
        { slug: data.slug },
        { $setOnInsert: data },
        { upsert: true, new: true },
      );
      const wasNew = result.createdAt.getTime() === result.updatedAt.getTime();
      if (wasNew) {
        console.log(`ADD    ${data.slug}`);
        added++;
      } else {
        console.log(`SKIP   ${data.slug}`);
      }
    } catch (err) {
      console.log(`FAIL   ${data.slug} — ${err.message}`);
      failed++;
    }
  }

  console.log(`\nDone. ${added} added, ${updated} updated, ${failed} failed.`);
  process.exit(failed > 0 ? 1 : 0);
}

// Guarded so importing `historyEvents` (e.g. from a one-off DB-sync script)
// doesn't also silently kick off this whole upsert loop in the background —
// the same race already caused a real incident in seedLocations.js
// (2026-09-16, see CLAUDE.md's KCD2 tie-in section) where a targeted update
// to an already-seeded doc raced this loop's own concurrent connection and
// got cut off before the write durably persisted.
if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  run().catch((err) => {
    console.error(err);
    process.exit(1);
  });
}
